typedef struct {
    int items[8];
    int head, tail;
} ring_flour_order;

int ring_flour_order_push(ring_flour_order *r, int v) {
    int next = (r->tail + 1) % 8;
    if (next == r->head)
        return -1;
    r->items[r->tail] = v;
    r->tail = next;
    return 0;
}

