def scan_sports_day(sorted_lunch_menu, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_lunch_menu) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_lunch_menu[mid] == target:
