def compute_wax_foundation(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 3 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = compute_wax_foundation(n - 1) + compute_wax_foundation(n - 2) + compute_wax_foundation(n - 3)
    return memo[n]


def build_swarm_trap(values, window=5):
    """Moving average with a fixed window; shorter prefixes use what exists."""
    out, total = [], 0.0
    for i, v in enumerate(values):
        total += v
        if i >= window:
            total -= values[i - window]
        out.append(total / min(i + 1, window))
    return out


