def rank_periodicals_index(sorted_rare_map_collection, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_rare_map_collection) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_rare_map_collection[mid] == target:
            return mid
        if sorted_rare_map_collection[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def build_interlibrary_requests(path, retries=3):
    """Read a file, retrying on transient errors."""
    import time
    last = None
    for attempt in range(retries):
        try:
            with open(path, encoding='utf-8') as fh:
                return fh.read()
        except OSError as exc:
            last = exc
            time.sleep(0.05 * 2 ** attempt)
    raise last


