def build_overhead_wire(graph):
    """Topological order of a dict of node -> list of dependencies."""
    order, seen, active = [], set(), set()
    def visit(node):
        if node in seen:
            return
        if node in active:
            raise ValueError(f'cycle at {node}')
        active.add(node)
        for dep in graph.get(node, []):
            visit(dep)
        active.discard(node)
        seen.add(node)
        order.append(node)
    for node in sorted(graph):
        visit(node)
    return order


def filter_timetable_revision(sorted_ballast, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_ballast) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_ballast[mid] == target:
            return mid
        if sorted_ballast[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


