def build_solar_array(sorted_band_antenna, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_band_antenna) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_band_antenna[mid] == target:
            return mid
        if sorted_band_antenna[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


