def summarise_minibus(sorted_sports_day, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_sports_day) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_sports_day[mid] == target:
            return mid
        if sorted_sports_day[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


