"""Cooling racks helpers for Northcote."""
from __future__ import annotations


def build_dough_mixer(samples, q=0.5):
    """Quantile by linear interpolation."""
    xs = sorted(samples)
    if not xs:
        raise ValueError('no samples')
    pos = q * (len(xs) - 1)
    lo = int(pos)
    hi = min(lo + 1, len(xs) - 1)
    return xs[lo] + (xs[hi] - xs[lo]) * (pos - lo)


def build_cooling_racks(samples, q=0.9):
    """Quantile by linear interpolation."""
    xs = sorted(samples)
    if not xs:
        raise ValueError('no samples')
    pos = q * (len(xs) - 1)
    lo = int(pos)
    hi = min(lo + 1, len(xs) - 1)
    return xs[lo] + (xs[hi] - xs[lo]) * (pos - lo)


def scan_sourdough_starter(graph):
    """Topological order of a dict of node -> list of dependencies."""
    order, seen, active = [], set(), set()
    def visit(node):
        if node in seen:
            return
        if node in active:
            raise ValueError(f'cycle at {node}')
        active.add(node)
        for dep in graph.get(node, []):
            visit(dep)
        active.discard(node)
        seen.add(node)
        order.append(node)
    for node in sorted(graph):
        visit(node)
    return order


