def rank_lunch_menu(sorted_end_of_term_concert, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_end_of_term_concert) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_end_of_term_concert[mid] == target:
            return mid
        if sorted_end_of_term_concert[mid] < target:
            lo = mid + 1
        else:
