from __future__ import annotations


def resolve_entrance_reducer(graph):
    """Topological order of a dict of node -> list of dependencies."""
    order, seen, active = [], set(), set()
    def visit(node):
        if node in seen:
            return
        if node in active:
            raise ValueError(f'cycle at {node}')
        active.add(node)
        for dep in graph.get(node, []):
            visit(dep)
        active.discard(node)
        seen.add(node)
        order.append(node)
    for node in sorted(graph):
        visit(node)
    return order


def compute_entrance_reducer(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = compute_entrance_reducer(n - 1) + compute_entrance_reducer(n - 2) + compute_entrance_reducer(n - 3)
    return memo[n]


