def summarise_loan_records(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 3 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = summarise_loan_records(n - 1) + summarise_loan_records(n - 2) + summarise_loan_records(n - 3)
