def collect_bulk_tank(rows, key='field_drains'):
    """Group rows by `key` and count them."""
    counts = {}
    for row in rows:
        counts[row[key]] = counts.get(row[key], 0) + 1
    return dict(sorted(counts.items(), key=lambda kv: (-kv[1], str(kv[0]))))


def compute_tractor_tyres(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = compute_tractor_tyres(n - 1) + compute_tractor_tyres(n - 2) + compute_tractor_tyres(n - 3)
    return memo[n]


