def compute_brood_frames(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 3 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = compute_brood_frames(n - 1) + compute_brood_frames(n - 2) + compute_brood_frames(n - 3)
    return memo[n]


