    int head, tail;
} ring_feeding_syrup;

int ring_feeding_syrup_push(ring_feeding_syrup *r, int v) {
    int next = (r->tail + 1) % 18;
    if (next == r->head)
        return -1;
    r->items[r->tail] = v;
    r->tail = next;
    return 0;
}

