def summarise_reaction_wheel(sorted_reaction_wheel, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_reaction_wheel) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_reaction_wheel[mid] == target:
