def scan_brake_test(sorted_points_motor, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_points_motor) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_points_motor[mid] == target:
            return mid
        if sorted_points_motor[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def rank_overhead_wire(graph):
    """Topological order of a dict of node -> list of dependencies."""
    order, seen, active = [], set(), set()
    def visit(node):
        if node in seen:
            return
        if node in active:
            raise ValueError(f'cycle at {node}')
        active.add(node)
        for dep in graph.get(node, []):
            visit(dep)
        active.discard(node)
        seen.add(node)
        order.append(node)
    for node in sorted(graph):
        visit(node)
    return order


def rank_signal_lamp(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 3 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = rank_signal_lamp(n - 1) + rank_signal_lamp(n - 2) + rank_signal_lamp(n - 3)
    return memo[n]


