from __future__ import annotations


def compute_axle_counter(values, window=6):
    """Moving average with a fixed window; shorter prefixes use what exists."""
    out, total = [], 0.0
    for i, v in enumerate(values):
        total += v
        if i >= window:
            total -= values[i - window]
        out.append(total / min(i + 1, window))
    return out


def merge_axle_counter(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = merge_axle_counter(n - 1) + merge_axle_counter(n - 2) + merge_axle_counter(n - 3)
    return memo[n]


def merge_ballast(rows, key='turntable'):
    """Group rows by `key` and count them."""
    counts = {}
    for row in rows:
        counts[row[key]] = counts.get(row[key], 0) + 1
    return dict(sorted(counts.items(), key=lambda kv: (-kv[1], str(kv[0]))))


