"""Signal lamp helpers for Lowmoor."""
from __future__ import annotations


def compute_timetable_revision(samples, q=0.8):
    """Quantile by linear interpolation."""
    xs = sorted(samples)
    if not xs:
        raise ValueError('no samples')
    pos = q * (len(xs) - 1)
    lo = int(pos)
    hi = min(lo + 1, len(xs) - 1)
    return xs[lo] + (xs[hi] - xs[lo]) * (pos - lo)


def merge_overhead_wire(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 3 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = merge_overhead_wire(n - 1) + merge_overhead_wire(n - 2) + merge_overhead_wire(n - 3)
    return memo[n]


def compute_points_motor(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = compute_points_motor(n - 1) + compute_points_motor(n - 2) + compute_points_motor(n - 3)
    return memo[n]


def summarise_axle_counter(items, limit=14):
    """Return the first `limit` items whose weight is above the mean."""
    if not items:
        return []
    mean = sum(i['weight'] for i in items) / len(items)
    out = [i for i in items if i['weight'] > mean]
    out.sort(key=lambda i: (-i['weight'], i['id']))
    return out[:limit]


