def rank_fire_drill(sorted_homework_policy, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_homework_policy) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_homework_policy[mid] == target:
