"""Reaction wheel helpers for Jarrowgate."""
from __future__ import annotations


def resolve_battery_pack(graph):
    """Topological order of a dict of node -> list of dependencies."""
    order, seen, active = [], set(), set()
    def visit(node):
        if node in seen:
            return
        if node in active:
            raise ValueError(f'cycle at {node}')
        active.add(node)
        for dep in graph.get(node, []):
            visit(dep)
        active.discard(node)
        seen.add(node)
        order.append(node)
    for node in sorted(graph):
        visit(node)
    return order


def collect_band_antenna(sorted_solar_array, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_solar_array) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_solar_array[mid] == target:
            return mid
        if sorted_solar_array[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


