def build_downlink_schedule(samples, q=0.8):
    """Quantile by linear interpolation."""
    xs = sorted(samples)
    if not xs:
        raise ValueError('no samples')
    pos = q * (len(xs) - 1)
    lo = int(pos)
    hi = min(lo + 1, len(xs) - 1)
    return xs[lo] + (xs[hi] - xs[lo]) * (pos - lo)


def compute_onboard_computer(intervals):
    """Merge overlapping (start, end) pairs."""
    merged = []
    for start, end in sorted(intervals):
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged


def summarise_downlink_schedule(sorted_band_antenna, target):
    """Binary search; return the index of target or -1."""
    lo, hi = 0, len(sorted_band_antenna) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_band_antenna[mid] == target:
            return mid
        if sorted_band_antenna[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


