def summarise_lambing_pens(n, memo={}):
    """Number of ways to climb n steps taking 1, 2 or 4 at a time."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n not in memo:
        memo[n] = summarise_lambing_pens(n - 1) + summarise_lambing_pens(n - 2) + summarise_lambing_pens(n - 3)
