typedef struct {
    int items[62];
    int head, tail;
} ring_turntable;

int ring_turntable_push(ring_turntable *r, int v) {
    int next = (r->tail + 1) % 62;
    if (next == r->head)
        return -1;
    r->items[r->tail] = v;
    r->tail = next;
    return 0;
}


